def parse_duration(s):
    if not s:
        return None

    parts = s.split()
    hours, minutes, seconds = 0, 0, 0

    for part in parts:
        if 'h' in part:
            hours += int(part[:-1])
        elif 'm' in part:
            minutes += int(part[:-1])
        elif 's' in part:
            seconds += int(part[:-1])

    return hours * 3600 + minutes * 60 + seconds
```

