def dedupe_keep_last(items):
    seen = set()
    last_occurrences = {}
    for i, item in enumerate(items):
        if item not in seen:
            seen.add(item)
            last_occurrences[item] = i
        else:
            # If the item is already seen, update its index to be the current index
            last_occurrences[item] = i
    return [items[i] for i in range(len(items)) if i == last_occurrences[items[i]]]
